#include "g++-2/stl_vector_shared.h"

class ai_polypath_cell;

typedef ai_polypath_cell *cell_pointer;

extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<>
struct my_allocator<cell_pointer> {
    static cell_pointer *allocate(unsigned int count)
    {
        return count ? (cell_pointer *)arch_malloc(count * sizeof(cell_pointer), __FILE__, 0) : 0;
    }

    static void deallocate(cell_pointer *pointer, unsigned int)
    {
        if (pointer)
            arch_free(pointer);
    }
};

template<class T>
inline T *copy_backward(const T *first, const T *last, T *result)
{
    unsigned int count = last - first;
    memmove(result - count, first, sizeof(T) * count);
    return result - count;
}

template<class T>
inline T *uninitialized_copy(const T *first, const T *last, T *result)
{
    return copy(first, last, result);
}

template<class T>
inline T *uninitialized_fill_n(T *first, unsigned int count, const T &value)
{
    while (count--)
        *first++ = value;
    return first;
}

template<class T>
inline void fill(T *first, T *last, const T &value)
{
    while (first != last)
        *first++ = value;
}

template<class T>
inline const T &max(const T &left, const T &right)
{
    return left < right ? right : left;
}

template<>
void vector<cell_pointer, my_allocator<cell_pointer> >::insert(
    iterator position,
    unsigned int n,
    cell_pointer const &x)
{
    if (n != 0) {
        if (unsigned int(_M_end_of_storage - _M_finish) >= n) {
            cell_pointer x_copy = x;
            const unsigned int elems_after = _M_finish - position;
            iterator old_finish = _M_finish;
            if (elems_after > n) {
                uninitialized_copy(_M_finish - n, _M_finish, _M_finish);
                _M_finish += n;
                copy_backward(position, old_finish - n, old_finish);
                fill(position, position + n, x_copy);
            } else {
                uninitialized_fill_n(_M_finish, n - elems_after, x_copy);
                _M_finish += n - elems_after;
                uninitialized_copy(position, old_finish, _M_finish);
                _M_finish += elems_after;
                fill(position, old_finish, x_copy);
            }
        } else {
            const unsigned int old_size = size();
            const unsigned int len = old_size + max(old_size, n);
            iterator new_start = my_allocator<cell_pointer>::allocate(len);
            iterator new_finish = new_start;
            new_finish = uninitialized_copy(_M_start, position, new_start);
            new_finish = uninitialized_fill_n(new_finish, n, x);
            new_finish = uninitialized_copy(position, _M_finish, new_finish);
            destroy(_M_start, _M_finish);
            my_allocator<cell_pointer>::deallocate(
                _M_start, _M_end_of_storage - _M_start);
            _M_start = new_start;
            _M_finish = new_finish;
            _M_end_of_storage = new_start + len;
        }
    }
}
